+		WHERE m.org_id=$1 AND u.email > $2 ORDER BY u.email LIMIT $3`, orgRoleNames, oid)
+}
+
+func hAddOrgMember(w http.ResponseWriter, r *http.Request, uid UUID) {
+	ctx := r.Context()
+	var in struct {
+		Email, Role json.RawMessage
+	}
+	if _, ok := decodeBody(w, r, &in); !ok {
