+	}
+	if len(v) > 0 {
+		errValidation(w, v)
+		return
+	}
+	if role >= orgAdmin && myRole < orgOwner {
+		errForbidden(w)
+		return
+	}
+	var tid UUID
+	var name string
+	err := db.QueryRow(ctx, "SELECT id, name FROM users WHERE email=$1", email).Scan(&tid, &name)
