var visNames = []string{"org", "private"}

var keyRe = regexp.MustCompile(`^[A-Z][A-Z0-9]{1,9}$`)

func effRole(orgRole, vis, pmRole int16) int16 {
	if orgRole >= orgAdmin {
		return prAdmin
	}
	r := pmRole
	if orgRole == orgMember && vis == 0 && r < prDeveloper {
		r = prDeveloper
	}
	return r
}

func parseProjRole(raw json.RawMessage) int16 {
	s, _ := str(raw)
	switch s {
	case "viewer":
		return prViewer
	case "developer":
		return prDeveloper
	case "admin":
		return prAdmin
	}
	return 0
}

type project struct {
	OrgID   UUID
	OrgRole int16
	ID      UUID
	Key     string
	Name    string
	Desc    pgtype.Text
	Vis     int16
	Created time.Time
	Role    int16 // effective
}

func appendProject(b []byte, p *project) []byte {
	b = append(b, `{"id":"`...)
	b = appendUUID(b, p.ID)
