		FROM orgs o JOIN org_members om ON om.org_id=o.id AND om.user_id=$3
		JOIN projects p ON p.org_id=o.id AND p.key=$2
		LEFT JOIN project_members pm ON pm.project_id=p.id AND pm.user_id=$3
