		if after, ok = parseUUID(s); !ok {
			errValidation1(w, "cursor", "invalid")
			return
		}
	}
	rows, err := db.Query(ctx, `SELECT id, url, events, active, created_at FROM webhooks WHERE org_id=$1 AND id > $2
		ORDER BY id LIMIT $3`, oid, after, limit+1)
	if err != nil {
		errInternal(w, err)
